/**
 * The manifest role the identity's roles name (by id or label, case-insensitive). FAILS CLOSED, like
 * the route guard's `canAccess`: with gating on, an identity that names none of the manifest's roles
 * (anonymous, or a role the prototype never declared) has NO role — never the default one's menu.
 */
function roleOf(raw: readonly string[]): string | null {
  if (!GATING) return null;
  const wanted = new Set(raw.map((r) => r.toLowerCase()));
  const hit = ROLES.find(
    (r) => wanted.has(r.id.toLowerCase()) || wanted.has(r.label.toLowerCase()),
  );
  return hit?.id ?? null;
}

/**
 * Every manifest role the identity names (by id or label, case-insensitive), in the manifest's order — the roles the
 * viewer HOLDS. The backend authorizes by their union; the active one only decides what the menu shows.
 */
function heldRolesOf(raw: readonly string[]): ShellViewModel['roles'] {
  if (!GATING) return [];
  const wanted = new Set(raw.map((r) => r.toLowerCase()));
  return ROLES.filter(
    (r) => wanted.has(r.id.toLowerCase()) || wanted.has(r.label.toLowerCase()),
  );
}

/** Up to two upper-case initials: first letters of the first and last word of the name. */
function initialsOf(name: string): string {
  const words = name.split(' ').filter((w) => w !== '');
  const first = words[0];
  if (first === undefined) return '';
  const last = words.length > 1 ? words[words.length - 1] : undefined;
  return (first.charAt(0) + (last === undefined ? '' : last.charAt(0))).toUpperCase();
}

/** The identity menu's data: the profile name (the e-mail when there is none) and the resolved role's label. */
function identityOf(
  who: ReturnType<typeof useIdentity>['identity'],
  roleLabel: string,
): ShellViewModel['identity'] {
  if (who === null || who === undefined) return null;
  const name = ((who.firstName ?? '') + ' ' + (who.lastName ?? '')).trim() || who.email;
  return {
    name,
    ...(who.email === '' ? {} : { email: who.email }),
    roleLabel,
    initials: initialsOf(name),
  };
}

